def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seed = next((r, c) for r in range(h) for c in range(w)
                if grid[r][c] == 2)

    r, c = seed
    if r == 0:
        dr, dc = 1, 0
    elif r == h - 1:
        dr, dc = -1, 0
    elif c == 0:
        dr, dc = 0, 1
    else:
        dr, dc = 0, -1

    queue = [(r, c, dr, dc)]
    visited = set()

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and grid[r][c] != 8:
            out[r][c] = 2

    while queue:
        r, c, dr, dc = queue.pop()
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] == 8:
                # Follow the edge of this barrier in both tangent directions.
                pr, pc = r - dr, c - dc
                tr, tc = -dc, dr
                for sign in (-1, 1):
                    qr, qc = pr, pc
                    while 0 <= qr < h and 0 <= qc < w:
                        paint(qr, qc)
                        wr, wc = qr + dr, qc + dc
                        if not (0 <= wr < h and 0 <= wc < w):
                            break
                        if grid[wr][wc] == 8:
                            qr += sign * tr
                            qc += sign * tc
                            continue

                        # The barrier has an opening here: pass through it
                        # and resume the ray on the far side.
                        paint(wr, wc)
                        nr, nc = wr + dr, wc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            queue.append((nr, nc, dr, dc))
                        break
                break

            state = (r, c, dr, dc)
            if state in visited:
                break
            visited.add(state)
            paint(r, c)
            r += dr
            c += dc

    return out
